#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Writing the COMPLETE appointments + medications feature bundle (all dependencies included)..."
mkdir -p api lib screens

echo "  lib/errorMessage.js"
mkdir -p "$(dirname 'lib/errorMessage.js')"
echo '' | base64 --decode > 'lib/errorMessage.js'

echo "  lib/medicationTime.js"
mkdir -p "$(dirname 'lib/medicationTime.js')"
echo '' | base64 --decode > 'lib/medicationTime.js'

echo "  lib/localNotifications.js"
mkdir -p "$(dirname 'lib/localNotifications.js')"
echo '' | base64 --decode > 'lib/localNotifications.js'

echo "  api/appointments.js"
mkdir -p "$(dirname 'api/appointments.js')"
echo '' | base64 --decode > 'api/appointments.js'

echo "  api/medications.js"
mkdir -p "$(dirname 'api/medications.js')"
echo '' | base64 --decode > 'api/medications.js'

echo "  screens/AppointmentsScreen.js"
mkdir -p "$(dirname 'screens/AppointmentsScreen.js')"
echo '' | base64 --decode > 'screens/AppointmentsScreen.js'

echo "  screens/SetReminderScreen.js"
mkdir -p "$(dirname 'screens/SetReminderScreen.js')"
echo '' | base64 --decode > 'screens/SetReminderScreen.js'

echo "  screens/ConfirmAppointmentScreen.js"
mkdir -p "$(dirname 'screens/ConfirmAppointmentScreen.js')"
echo '' | base64 --decode > 'screens/ConfirmAppointmentScreen.js'

echo "  screens/InputMedicationsScreen.js"
mkdir -p "$(dirname 'screens/InputMedicationsScreen.js')"
echo '' | base64 --decode > 'screens/InputMedicationsScreen.js'

echo "  screens/MedicationReminderScreen.js"
mkdir -p "$(dirname 'screens/MedicationReminderScreen.js')"
echo '' | base64 --decode > 'screens/MedicationReminderScreen.js'

echo "  screens/MedicationsScreen.js"
mkdir -p "$(dirname 'screens/MedicationsScreen.js')"
echo '' | base64 --decode > 'screens/MedicationsScreen.js'

echo "  screens/HomeScreen.js"
mkdir -p "$(dirname 'screens/HomeScreen.js')"
echo '' | base64 --decode > 'screens/HomeScreen.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "  package.json"
mkdir -p "$(dirname 'package.json')"
echo '' | base64 --decode > 'package.json'

echo "  app.json"
mkdir -p "$(dirname 'app.json')"
echo '' | base64 --decode > 'app.json'

echo "Installing dependencies (expo-notifications, and anything else missing)..."
npx expo install expo-notifications

echo ""
echo "Done. This is a complete snapshot - safe to run even if some of these files already exist correctly on your machine."
